<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue'
import {Download,Search,X} from 'lucide-vue-next'
import type {AccountSummary,AuditEvent,AuditEventDetail,DownloadTicket,JobAccepted,JobStatus,Page,ShtongApi} from '@shtong/api-sdk'
import {eventCodes,localTime,saveBlob,zh} from '@shtong/web-shared'
import {useAction} from '../composables/useAction'
import AccountPicker from './AccountPicker.vue'
import ActionFeedback from './ActionFeedback.vue'
const props=defineProps<{api:ShtongApi}>(),events=ref<AuditEvent[]>([]),selected=ref<AuditEventDetail>(),exportJobId=ref(sessionStorage.getItem('shtong.pendingAuditExport')||''),next=ref<string>(),names=ref<Record<string,string>>({})
const {busy,error,notice,run}=useAction()
const today=new Date(),start=new Date(today);start.setDate(start.getDate()-7)
const dateInput=(date:Date)=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`
const filter=reactive({eventCode:'',actorAccountId:'',subjectAccountId:'',purpose:'核查操作记录',from:dateInput(start),to:dateInput(today)})
function range(){const from=new Date(filter.from+'T00:00:00'),to=new Date(filter.to+'T00:00:00');to.setDate(to.getDate()+1);if(!Number.isFinite(from.getTime())||!Number.isFinite(to.getTime())||to<=from||to.getTime()-from.getTime()>31*86400000)throw {messageKey:'error.audit.range'};return {occurredFrom:from.toISOString(),occurredTo:to.toISOString()}}
function query(){const p=new URLSearchParams(range());for(const key of ['eventCode','actorAccountId','subjectAccountId'] as const)if(filter[key])p.set(key,filter[key]);return p}
async function resolveName(id:string){if(names.value[id])return;try{const account=await props.api.request<AccountSummary>(`/system/accounts/${id}`);names.value[id]=`${account.displayName}（${account.loginName}）`}catch{names.value[id]='账户信息暂不可用'}}
function load(more=false){void run(async()=>{const params=query();if(more&&next.value)params.set('cursor',next.value);const result=await props.api.request<Page<AuditEvent>>(`/system/audit/events?${params}`);events.value=more?[...events.value,...result.items]:result.items;next.value=result.nextCursor||undefined;await Promise.all([...new Set(result.items.flatMap(item=>item.actorAccountId?[item.actorAccountId]:[]))].map(resolveName))})}
function detail(id:string){void run(async()=>{selected.value=await props.api.request<AuditEventDetail>(`/system/audit/events/${id}`);await Promise.all(selected.value.subjects.map(resolveName))})}
function requestExport(){void run(async()=>{if(filter.purpose.trim().length<2){error.value='请填写导出用途';return}const job=await props.api.request<JobAccepted>('/system/audit/export-jobs',{method:'POST',body:JSON.stringify({...range(),eventCodes:filter.eventCode?[filter.eventCode]:undefined,actorAccountId:filter.actorAccountId||undefined,subjectAccountId:filter.subjectAccountId||undefined,purpose:filter.purpose})});exportJobId.value=job.jobId;sessionStorage.setItem('shtong.pendingAuditExport',job.jobId);notice.value='导出申请已提交，等待另一位管理员在“安全复核”中确认。'})}
function refreshExport(){void run(async()=>{const status=await props.api.request<JobStatus>(`/system/audit/export-jobs/${exportJobId.value}`);if(status.state!=='READY'){notice.value=`操作记录导出：${zh(status.state)}`;return}const ticket=await props.api.request<DownloadTicket>(`/system/audit/export-jobs/${exportJobId.value}/download-ticket`,{method:'POST'});saveBlob(await props.api.download(ticket),'操作记录.csv');notice.value=`已下载 ${status.resultCount??0} 条操作记录`;exportJobId.value='';sessionStorage.removeItem('shtong.pendingAuditExport')})}
function translated(value:unknown):unknown{if(Array.isArray(value))return value.map(translated);if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([key,item])=>[zh(key),translated(item)]));return typeof value==='string'?zh(value):value}
onMounted(()=>load())
</script>
<template><section class="view"><header class="page-header"><h1>操作记录</h1></header><form class="tool-panel create-grid" @submit.prevent="load()"><label>开始日期<input v-model="filter.from" type="date" required></label><label>结束日期<input v-model="filter.to" type="date" required></label><label>操作类型<select v-model="filter.eventCode"><option value="">全部操作</option><option v-for="code in eventCodes" :key="code" :value="code">{{zh(code)}}</option></select></label><label>导出用途<input v-model="filter.purpose" minlength="2" maxlength="500" required></label><div class="form-actions"><button class="primary" :disabled="busy"><Search :size="18" aria-hidden="true"/>查询</button><button type="button" class="secondary" :disabled="busy" @click="requestExport"><Download :size="18" aria-hidden="true"/>申请导出</button></div></form><details class="advanced-filter"><summary>按人员筛选</summary><div class="two-columns"><AccountPicker v-model="filter.actorAccountId" :api="api" label="操作人"/><AccountPicker v-model="filter.subjectAccountId" :api="api" label="涉及的人员"/></div></details><ActionFeedback :error="error" :notice="notice" :busy="busy"/><button v-if="exportJobId" class="secondary" :disabled="busy" @click="refreshExport">查看导出结果并下载</button><div class="audit-layout"><div class="record-list"><button v-for="event in events" :key="event.eventId" class="audit-row" :disabled="busy" @click="detail(event.eventId)"><span><strong>{{zh(event.eventCode)}}</strong><small>{{localTime(event.occurredAt)}} · {{event.actorAccountId?names[event.actorAccountId]||'正在读取':'系统或未登录人员'}}</small></span><span class="status" :class="event.outcome.toLowerCase()">{{zh(event.outcome)}}</span></button><p v-if="!events.length" class="empty">没有匹配的操作记录</p><button v-if="next" class="secondary" :disabled="busy" @click="load(true)">更多记录</button></div><aside class="detail-panel" aria-live="polite"><template v-if="selected"><header><h2>操作详情</h2><button class="icon-button" aria-label="关闭详情" @click="selected=undefined"><X :size="19" aria-hidden="true"/></button></header><dl class="detail-list"><dt>操作</dt><dd>{{zh(selected.eventCode)}}</dd><dt>操作时间</dt><dd>{{localTime(selected.occurredAt)}}</dd><dt>操作人</dt><dd>{{selected.actorAccountId?names[selected.actorAccountId]:'系统或未登录人员'}}</dd><dt>权限校验</dt><dd>{{zh(selected.authorizationDecision)}}</dd><dt>结果</dt><dd>{{zh(selected.outcome)}}</dd><dt>涉及人员</dt><dd>{{selected.subjects.map(id=>names[id]||'账户信息暂不可用').join('、')||'无'}}</dd></dl><details><summary>详细变更与校验记录</summary><h3>对象</h3><pre>{{JSON.stringify(translated(selected.resources),null,2)}}</pre><h3>内容变化</h3><pre>{{JSON.stringify(translated(selected.changes),null,2)}}</pre><h3>权限校验依据</h3><pre>{{JSON.stringify(translated(selected.authorizationEvidence),null,2)}}</pre><p>记录编号：{{selected.eventId}}</p><p>请求编号：{{selected.requestId}}</p></details></template><p v-else class="empty">尚未选择操作记录</p></aside></div></section></template>
